// Purpose: Calculates and displays the time elapsed since the last DMI data update.
// Inputs: None directly from msg.payload. Relies on a global variable 'lastDMIUpdate'.
// Outputs: Modifies msg.payload to a string indicating the time since the last update (e.g., "5 minutes ago").
//          If no update has occurred yet, it returns "Waiting for first update...".
// Global Interaction: Reads 'lastDMIUpdate' from global context, which is expected to be set by other nodes
//                    when new DMI data is successfully fetched and processed.

const lastUpdate = global.get('lastDMIUpdate'); // Retrieve the timestamp of the last DMI update.
if (!lastUpdate) {
    // If 'lastDMIUpdate' is not set, it means no data has been received yet.
    msg.payload = 'Waiting for first update...';
    return msg;
}

// Calculate the difference in milliseconds between now and the last update, then convert to minutes.
const minutesAgo = Math.round((Date.now() - lastUpdate) / 60000);
msg.payload = `${minutesAgo} minutes ago`; // Format the output string.
return msg;

// Purpose: Processes forecasted water level data from DMI, buffers it, and sends valid future predictions.
//          It also updates the node status with the latest data and buffer size.
// Inputs: msg.payload.features - An array of forecast data points from a DMI API response.
// Outputs: Sends a new message for each valid future water level prediction.
//          - msg.payload: Water level in centimeters (rounded).
//          - msg.topic: "Sea water level, cm".
//          - msg.timestamp: Timestamp of the forecast step.
//          Sends 'null' if no valid future data is found or if input is empty and buffer is also empty.
// Context Interaction:
//          - context.get('dataBuffer'): Retrieves a buffer of recent data points.
//          - context.set('dataBuffer', buffer): Saves the updated buffer (max size MAX_BUFFER_SIZE).
// Global Interaction:
//          - global.set('lastDMIUpdate', dateNow.getTime()): Updates global timestamp on successful data processing.
// Initialization: 'dataBuffer' is initialized as an empty array, 'lastDMIUpdate' to null.
// Error Handling/Fallback:
//          - If msg.payload.features is empty, it warns and attempts to use data from 'dataBuffer'.
//          - If both input and buffer are empty, returns null and sets status to "No data".
//          - If no *future* predictions are found, warns and sets status accordingly.

let array = msg.payload.features || []; // Input array of DMI forecast features.
let dateNow = new Date(); // Current date and time.

// Get or initialize buffer for storing recent data points.
let buffer = context.get('dataBuffer') || [];
const MAX_BUFFER_SIZE = 60; // Defines the maximum number of data points to keep in the buffer (e.g., 1 minute of data at 1 reading/second).

// Handle empty input array.
if (!array.length) {
    node.warn('No water level data received');
    node.status({fill:"red", shape:"ring", text:"No data"});

    // If input is empty but buffer has data, use buffered data.
    if (buffer.length > 0) {
        node.warn('Using buffered data');
        array = buffer; // Replace empty input with buffered data.
    } else {
        // If both input and buffer are empty, nothing to process.
        return null;
    }
}

let foundValidData = false; // Flag to track if any valid future data was processed.

// Iterate through the array of forecast data points.
for (let i = 0; i < array.length; i++) {
    let dateTest = new Date(array[i].properties.step); // Timestamp of the current forecast step.

    // Process data only if its timestamp is in the future (or current).
    if (dateTest - dateNow >= 0) {       // Don't send old data 
        // Extract and round water level (sea-mean-deviation). Default to 0 if not present.
        const waterLevel = Math.round(100 * (array[i].properties['sea-mean-deviation'] || 0));

        // Prepare the output message.
        msg.payload = waterLevel;
        msg.topic = "Sea water level, cm";
        msg.timestamp = array[i].properties.step;

        // Add current data point to buffer.
        buffer.push(array[i]);
        if (buffer.length > MAX_BUFFER_SIZE) {
            buffer.shift(); // Remove the oldest entry if buffer exceeds max size.
        }

        // Update last DMI update time in global context.
        global.set('lastDMIUpdate', dateNow.getTime());

        // Update node status to show current water level and buffer size.
        node.status({fill:"green", shape:"dot", 
            text:`Level: ${waterLevel}cm at ${dateTest.toLocaleTimeString()} (Buffer: ${buffer.length})`});
        foundValidData = true;
        node.send(msg); // Send the processed message.
    }
}

// Save the updated buffer to context.
context.set('dataBuffer', buffer);

// If no valid future data was found in this run.
if (!foundValidData) {
    node.warn('No future water level predictions found');
    // Update node status to indicate no future data, but show current buffer size.
    node.status({fill:"yellow", shape:"ring", text:`No future data (Buffer: ${buffer.length})`});
}

node.done(); // Signal completion of asynchronous operations, if any.
return null; // This function sends messages via node.send(), so return null here.

// Purpose: Processes forecasted wind speed and direction data from DMI, buffers it,
//          and sends valid future predictions as two separate messages.
//          It also updates the node status with the latest data and buffer size.
// Inputs: msg.payload.features - An array of forecast data points from a DMI API response.
// Outputs: Sends two messages for each valid future forecast point:
//          1. Wind Speed:
//             - msg.payload: Wind speed in m/s (rounded to one decimal).
//             - msg.topic: "Wind speed m/s".
//             - msg.timestamp: Timestamp of the forecast step.
//          2. Wind Direction:
//             - msg.payload: Wind direction in degrees (rounded).
//             - msg.topic: "Wind direction degrees".
//             - msg.timestamp: Timestamp of the forecast step.
//          Sends 'null' if no valid future data is found or if input is empty and buffer is also empty.
// Context Interaction:
//          - context.get('dataBuffer'): Retrieves a buffer of recent data points.
//          - context.set('dataBuffer', buffer): Saves the updated buffer (max size MAX_BUFFER_SIZE).
// Initialization: 'dataBuffer' is initialized as an empty array.
// Error Handling/Fallback:
//          - If msg.payload.features is empty, it warns and attempts to use data from 'dataBuffer'.
//          - If both input and buffer are empty, returns null and sets status to "No data".
//          - If no *future* predictions are found, warns and sets status accordingly.

let array = msg.payload.features || []; // Input array of DMI forecast features.
let dateNow = new Date(); // Current date and time.

// Get or initialize buffer for storing recent data points.
let buffer = context.get('dataBuffer') || [];
const MAX_BUFFER_SIZE = 60; // Defines the maximum number of data points to keep in the buffer.

// Handle empty input array.
if (!array.length) {
    node.warn('No wind data received');
    node.status({fill:"red", shape:"ring", text:"No data"});

    // If input is empty but buffer has data, use buffered data.
    if (buffer.length > 0) {
        node.warn('Using buffered data');
        array = buffer; // Replace empty input with buffered data.
    } else {
        // If both input and buffer are empty, nothing to process.
        return null;
    }
}

let foundValidData = false; // Flag to track if any valid future data was processed.

// Iterate through the array of forecast data points.
for (let i = 0; i < array.length; i++) {
    let dateTest = new Date(array[i].properties.step); // Timestamp of the current forecast step.

    // Process data only if its timestamp is in the future (or current).
    if (dateTest - dateNow >= 0) {       // Don't send old data 
        // Extract and round wind speed. Default to 0 if not present.
        const windSpeed = Math.round((array[i].properties['wind-speed'] || 0) * 10) / 10;
        // Extract and round wind direction. Default to 0 if not present.
        const windDir = Math.round(array[i].properties['wind-dir'] || 0);

        // Prepare the wind speed message.
        let wind = {
            payload: windSpeed,
            topic: "Wind speed m/s",
            timestamp: array[i].properties.step
        };

        // Prepare the wind direction message.
        let direction = {
            payload: windDir,
            topic: "Wind direction degrees",
            timestamp: array[i].properties.step
        };

        // Add current data point to buffer.
        buffer.push(array[i]);
        if (buffer.length > MAX_BUFFER_SIZE) {
            buffer.shift(); // Remove the oldest entry if buffer exceeds max size.
        }

        // Update node status to show current wind data and buffer size.
        node.status({fill:"green", shape:"dot", 
            text:`${windSpeed}m/s at ${windDir}° (Buffer: ${buffer.length})`});
        foundValidData = true;
        // Send wind speed and wind direction as two separate messages on two outputs.
        node.send([wind, direction]); 
    }
}

// Save the updated buffer to context.
context.set('dataBuffer', buffer);

// If no valid future data was found in this run.
if (!foundValidData) {
    node.warn('No future wind predictions found');
    // Update node status to indicate no future data, but show current buffer size.
    node.status({fill:"yellow", shape:"ring", text:`No future data (Buffer: ${buffer.length})`});
}

node.done(); // Signal completion of asynchronous operations, if any.
return null; // This function sends messages via node.send(), so return null here.

// Purpose: Formats incoming SignalK GPS position data, checks for connection stability,
//          calculates distance moved and time passed since last update,
//          and decides whether to send an update for DMI API requests.
//          It aims to reduce API calls by only updating if the vessel has moved significantly (>= 5nm)
//          or a certain time has passed (>= 1 hour).
// Inputs: msg.payload from SignalK, expected to contain 'longitude' and 'latitude'.
// Outputs:
//          - Modifies msg.position to "POINT(lon lat)" format if an update is needed.
//          - Sets msg.retry to true/false.
//          - Sends the modified msg if an update is warranted or retry is needed.
//          - Sends null if no update is needed.
// Context Interaction:
//          - context.get/set('lastReceived'): Timestamp of the last valid data received, for connection health.
//          - context.get/set('lastGoodPosition'): Stores the last valid {lat, lon, position} object. Used for fallback.
//          - context.get/set('lastUpdate'): Timestamp of the last time an update was sent to DMI.
//          - context.get/set('lastPos'): Stores {lat, lon} of the last position sent to DMI.
//          - context.get/set('latestPosition'): Stores the "POINT(lon lat)" string of the last position sent to DMI.
// Initialization: Clears all stored position and time context variables on deploy.
// Error Handling/Fallback:
//          - Monitors time since last data: sets status to red (>30s) or yellow (>10s).
//          - If coordinates are invalid: warns. If 'lastGoodPosition' exists, uses it.
//            If no 'latestPosition' (first run after deploy with bad data), sets msg.retry = true. Otherwise returns null.
// Logic:
//          - Haversine formula is used to calculate distance between two lat/lon points.
//          - Update sent if:
//              - Distance moved >= 5 nautical miles OR
//              - Time since last DMI update >= 1 hour OR
//              - No previous DMI update has been sent ('lastUpdate' is null).

// --- Connection Health Tracking ---
const lastReceived = context.get('lastReceived') || 0; // Timestamp of last data packet.
const timeNow = Date.now();
const timeSinceLastData = (timeNow - lastReceived) / 1000; // Time in seconds since last data.

// Update node status based on connection health.
if (timeSinceLastData > 30) { // No data for 30 seconds
    node.status({fill:"red", shape:"ring", text:"SignalK Connection Lost"});
} else if (timeSinceLastData > 10) { // No data for 10 seconds
    node.status({fill:"yellow", shape:"ring", text:"SignalK Connection Unstable"});
}
// Note: A green status will be set later if data is processed successfully.

const lon = msg.payload.longitude;
const lat = msg.payload.latitude;

// --- Input Validation and Fallback ---
// Check for valid coordinates.
if (lon === undefined || lat === undefined || isNaN(lon) || isNaN(lat)) {
    node.warn("Position data invalid - lon: " + lon + ", lat: " + lat);

    // Try to use the last known good position if current data is invalid.
    const lastGoodPos = context.get('lastGoodPosition');
    if (lastGoodPos) {
        node.warn("Using last known good position: " + JSON.stringify(lastGoodPos));
        msg.position = lastGoodPos.position; // Use the formatted string.
        // This message will likely be filtered out by distance/time checks, but provides a valid position.
        // Or, if this is the first message, it might trigger an update if conditions are met.
        // We don't set msg.retry here because we have *some* data.
        return msg; // Proceed with last good position
    }

    // If there's no 'latestPosition' (meaning no successful DMI update yet)
    // and current data is bad, set retry flag to try again later.
    if (!context.get('latestPosition')) {
        msg.retry = true; // Signal to retry this message later.
        return msg;
    }
    // If 'latestPosition' exists, but current data is bad, and no 'lastGoodPos', then drop this message.
    return null; 
}

// --- Update Context with Valid Data ---
// If coordinates are valid, update last received time and store this position as the last good one.
context.set('lastReceived', timeNow);
context.set('lastGoodPosition', { lat: lat, lon: lon, position: `POINT(${lon} ${lat})` });

const roundedLon = Number(lon).toFixed(4); // Round longitude for DMI query.
const roundedLat = Number(lat).toFixed(4); // Round latitude for DMI query.

// --- Check if DMI Update is Needed ---
const lastUpdate = context.get('lastUpdate') || 0; // Timestamp of the last DMI update.
const lastPos = context.get('lastPos'); // Last {lat, lon} used for DMI update.

let distance = 0; // Calculated distance from last DMI update position.
if (lastPos) {
    // Haversine formula to calculate distance between two points on Earth.
    const R = 6371; // Earth's radius in km.
    const dLat = (lat - lastPos.lat) * Math.PI / 180;
    const dLon = (lon - lastPos.lon) * Math.PI / 180;
    const a = Math.sin(dLat/2) * Math.sin(dLat/2) +
              Math.cos(lastPos.lat * Math.PI / 180) * Math.cos(lat * Math.PI / 180) * 
              Math.sin(dLon/2) * Math.sin(dLon/2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
    distance = R * c; // Distance in kilometers.
}

distance = distance * 0.539957; // Convert distance to nautical miles.

const hoursPassed = (timeNow - lastUpdate) / (1000 * 60 * 60); // Hours since last DMI update.

// Determine if an update should be sent to DMI.
// Conditions: Moved >= 5nm OR >= 1 hour passed OR it's the first update.
if (distance >= 5 || hoursPassed >= 1 || !lastUpdate) {
    msg.position = `POINT(${roundedLon} ${roundedLat})`; // Set formatted position for DMI query.
    context.set('latestPosition', msg.position); // Store the latest position sent to DMI.
    context.set('lastUpdate', timeNow); // Update timestamp of this DMI update.
    context.set('lastPos', { lat: Number(lat), lon: Number(lon) }); // Store current lat/lon for next distance calculation.

    node.status({fill:"green", shape:"dot", text:`Updated: Distance=${distance.toFixed(1)}nm, Time=${hoursPassed.toFixed(1)}h`});
    msg.retry = false; // No need to retry this message.
    return msg; // Send the message for DMI request.
} else {
    // Conditions for update not met, skip sending to DMI.
    node.status({fill:"blue", shape:"ring", text:`Skipped: Distance=${distance.toFixed(1)}nm, Time=${hoursPassed.toFixed(1)}h`});
    return null; // Do not send a message.
}

initialize:
// Clear stored position and time on deploy
context.set('lastUpdate', null);
context.set('lastPos', null);
context.set('latestPosition', null);
context.set('lastReceived', null);
context.set('lastGoodPosition', null);
context.set('dataBuffer', []);
